import re
from fractions import Fraction
from math import floor, ceil

# Milliseconds represented by each unit.
_UNIT_MS = {
    'w': 7 * 24 * 3600 * 1000,   # 7 days
    'd': 24 * 3600 * 1000,       # 24 hours
    'h': 3600 * 1000,
    'm': 60 * 1000,              # minutes
    's': 1000,
    'ms': 1,
}

# Order of units from largest to smallest.
_ORDER = {'w': 0, 'd': 1, 'h': 2, 'm': 3, 's': 4, 'ms': 5}

# A component is a non-negative decimal number directly followed by a unit.
# `ms` is listed before `m`/`s` so the two-character unit is matched first.
_TOKEN_RE = re.compile(r'(\d+(?:\.\d+)?)(ms|w|d|h|m|s)')


def _round_half_away_from_zero(x):
    """Round a Fraction to the nearest int, with exact halves away from zero."""
    if x >= 0:
        return floor(x + Fraction(1, 2))
    return ceil(x - Fraction(1, 2))


def parse_duration(text):
    """Return the duration described by `text` in whole milliseconds.

    See TASK.md for the full specification.
    """
    if not isinstance(text, str):
        raise TypeError("duration text must be a str, got %r" % type(text).__name__)

    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    # A single leading '-' negates the whole duration; '+' is invalid.
    negative = False
    if s[0] == '-':
        negative = True
        s = s[1:]
    elif s[0] == '+':
        raise ValueError("leading '+' is invalid")

    if not s:
        raise ValueError("duration has no components")

    tokens = list(_TOKEN_RE.finditer(s))
    if not tokens:
        raise ValueError("invalid duration: %r" % text)

    # Validate the overall structure: components are separated by nothing or
    # by exactly one space, and nothing extra may surround them.
    pos = 0
    components = []
    for i, tok in enumerate(tokens):
        gap = s[pos:tok.start()]
        if i == 0:
            if gap != '':
                raise ValueError("invalid duration: %r" % text)
        else:
            if gap not in ('', ' '):
                raise ValueError("invalid duration: %r" % text)
        components.append((tok.group(1), tok.group(2)))
        pos = tok.end()
    if pos != len(s):
        raise ValueError("invalid duration: %r" % text)

    # Enforce strictly descending unit order, no repeated units, and that only
    # the last component may carry a fraction.
    prev_order = None
    for i, (number, unit) in enumerate(components):
        order = _ORDER[unit]
        if prev_order is not None and order <= prev_order:
            raise ValueError("units must be in strictly descending order: %r" % text)
        prev_order = order
        if '.' in number and i != len(components) - 1:
            raise ValueError("only the last component may have a fraction: %r" % text)

    # Compute the exact total in milliseconds, then round to the nearest
    # millisecond (halves away from zero).
    total = Fraction(0)
    for number, unit in components:
        total += Fraction(number) * _UNIT_MS[unit]

    magnitude = _round_half_away_from_zero(total)
    return -magnitude if negative else magnitude
